    if isinstance(G,Exception): raise G
    return G
def exp(G,s):
    P,p=parse(s); Pi=np.linalg.inv(P)
    return [(P@np.asarray(op.rotation_matrix,float)@Pi,
             (P@np.asarray(op.translation_vector,float)+p-(P@np.asarray(op.rotation_matrix,float)@Pi)@p)%1,
